// ==UserScript==
// @name             SMG iPad 请求助手
// @namespace        http://tampermonkey.net/
// @version          0.26.0
// @description      收看SMGTV，并解除页面部分限制
// @author           https://github.com/Popukok
// @match            *://*.kankanews.com/huikan*
// @icon             https://live.kankanews.com/favicon.ico
// @run-at           document-start
// @inject-into      content
// @grant            GM.xmlHttpRequest
// @grant            GM_xmlhttpRequest
// @connect          kapi.kankanews.com
// @noframes
// @weight           900
// ==/UserScript==
// Generated by scripts/build-ipad.cjs; do not edit this copy manually.
(function installRequestHelper() {
    'use strict';
    if (globalThis.__smgIpadHelperLoaded) return;
    globalThis.__smgIpadHelperLoaded = true;
    const REQUEST = 'smgtv-ipad-api-request';
    const RESPONSE = 'smgtv-ipad-api-response';
    const allowedHeaders = new Set([
        'accept', 'platform', 'version', 'nonce', 'timestamp', 'api-version', 'sign',
        'm-uuid', 'channel_program_id', 'channel_id', 'date'
    ]);
    const seen = new Map();
    const emit = message => document.dispatchEvent(new CustomEvent(RESPONSE, { detail: JSON.stringify(message) }));
    function validate(message) {
        if (!message || typeof message.id !== 'string' || message.id.length > 200 || typeof message.url !== 'string') return null;
        try {
            const url = new URL(message.url);
            if (url.origin !== 'https://kapi.kankanews.com' || url.username || url.password || url.hash) return null;
            const params = url.searchParams;
            if (url.pathname === '/content/pc/tv/program/detail') {
                if ([...params.keys()].length !== 1 || !/^\d+$/.test(params.get('channel_program_id') || '')) return null;
            } else if (url.pathname === '/content/pc/tv/programs') {
                if ([...params.keys()].length !== 2 || !/^\d+$/.test(params.get('channel_id') || '') ||
                        !/^\d{4}-\d{2}-\d{2}$/.test(params.get('date') || '')) return null;
            } else return null;
            const headers = {};
            Object.keys(message.headers || {}).forEach(key => {
                const value = message.headers[key];
                if (allowedHeaders.has(key.toLowerCase()) && (typeof value === 'string' || typeof value === 'number') &&
                        String(value).length <= 2000 && !/[\r\n]/.test(String(value))) headers[key] = String(value);
            });
            return { url: url.href, headers };
        } catch (e) { return null; }
    }
    document.addEventListener(REQUEST, event => {
        let message;
        if (typeof event.detail !== 'string' || event.detail.length > 16000) return;
        try { message = JSON.parse(event.detail); } catch (e) { return; }
        const request = validate(message);
        if (!request) return;
        for (const [id, entry] of seen) {
            if (entry.done && Date.now() - entry.at > 60000) seen.delete(id);
        }
        const existing = seen.get(message.id);
        if (existing) {
            emit(existing.response || { id: message.id, kind: 'started' });
            return;
        }
        if ([...seen.values()].filter(entry => !entry.done).length >= 4) {
            emit({ id: message.id, kind: 'error' });
            return;
        }
        // Keep replay protection bounded while preserving all in-flight requests.
        for (const [id, entry] of seen) {
            if (seen.size < 64) break;
            if (entry.done) seen.delete(id);
        }
        const entry = { at: Date.now(), done: false, response: null };
        seen.set(message.id, entry);
        emit({ id: message.id, kind: 'started' });
        let handle;
        const finish = (kind, response) => {
            if (entry.done) return;
            entry.done = true;
            clearTimeout(timer);
            entry.response = { id: message.id, kind, response };
            emit(entry.response);
        };
        const timer = setTimeout(() => {
            finish('timeout');
            try { handle?.abort(); } catch (e) {}
        }, 15000);
        const details = {
            method: 'GET', url: request.url, headers: request.headers, timeout: 15000, responseType: 'text',
            onload: response => finish('load', { status: response.status, responseText: response.responseText }),
            onerror: () => finish('error'), ontimeout: () => finish('timeout'), onabort: () => finish('abort')
        };
        try {
            if (typeof GM !== 'undefined' && typeof GM.xmlHttpRequest === 'function') {
                handle = GM.xmlHttpRequest(details);
                // Userscripts exposes a Promise; callback-only managers are supported too.
                if (handle && typeof handle.then === 'function') handle.then(details.onload, details.onerror);
            } else if (typeof GM_xmlhttpRequest === 'function') {
                handle = GM_xmlhttpRequest(details);
            } else finish('error');
        } catch (e) { finish('error'); }
    });
})();
